 for(const p of molDefinitions.people){const a=state.actors[p.id];assert(natural(a.resources['book.mol.crowns'])&&natural(a.resources['book.mol.attention']),'Resident purses/attention must be their own nonnegative finite means.');}
 assert(natural(state.actors[I.nora].resources['book.mol.personalMana'])&&state.actors[I.nora].resources['book.mol.personalMana']<=18&&natural(state.actors[I.taiven].resources['book.mol.personalMana'])&&state.actors[I.taiven].resources['book.mol.personalMana']<=12,'Named specialist attuned reserves exceed the authored capacity.');
 const same=(x,y)=>JSON.stringify(x)===JSON.stringify(y);
 for(const j of s.jobs.filter(j=>optionalPrefix(j.commandId))){const def=molCommands.find(c=>c.id===j.commandId);assert(def&&def.duration>0&&j.actorId===def.actorId&&j.targetId===(def.targetId||null)&&j.context?.actorId===def.actorId&&j.context.targetId===(def.targetId||null)&&j.revision===def.revision&&j.reservationReturns===1&&j.cancellation==='refund'&&j.siteId===(def.siteId||null)&&j.claim===(def.claim||null)&&same(j.costs,def.costs)&&same(j.effects,def.effects)&&same(j.participants,[def.actorId,...(def.targetId?[def.targetId]:[])])&&j.completionSupport?.schema===1&&j.completionSupport.failure==='refund'&&j.completionSupport.location===def.location&&j.completionSupport.coLocated===!!def.completionCoLocated&&same(j.completionSupport.requires,def.completionRequires),'Cyorian work differs from its exact admitted owner, physical reservations, support or frozen revision.');}
 for(const [actor,session]of Object.entries(s.sessions).filter(([,session])=>optionalPrefix(session.commandId||''))){const def=molCommands.find(c=>c.id===session.commandId),encounter=molDefinitions.encounters.find(e=>e.id===session.definitionId);assert(actor==='player'&&def?.encounterId===I.encounter&&encounter&&session.revision===1&&session.targetId===I.opponent&&session.lethal===false&&!session.nativeBattle&&same(session.turns,encounter.turns)&&same(session.settlement,encounter.settlement)&&session.claim==='book.mol.retrieval.resolution'&&visit,'Cyorian opposed encounter needs its exact frozen native participants and retained local visit.');}
 for(const [actor,program]of Object.entries(s.programs||{}))assert(!optionalPrefix(program.commandId||''),'Choose each Cyorian job deliberately; no automatic source campaign routine is admitted.');
