 assert(a.resources['book.mol.personalMana']==null,'Independent entry must not invent personal Cyorian casting fuel.');
 if(charge>0)assert(a.facts['book.mol.lampBuilt']===true&&a.facts['book.mol.deviceCapacity']===6&&a.sources[I.operator]&&s.powers.player?.[I.operator]?.owned,'Stored charge needs the actual built and learned device owner.');
 if(a.facts['book.mol.assessment']!=null)assert(a.facts['book.mol.assessment']==='no_demonstrated_source','Unselected casting talent cannot be imported as an assessment result.');
 const reportDone=a.completed['book.mol.report_to_taiven']===1,received=s.knowledge[I.taiven]?.['book.mol.receivedSurvey'];
 assert(reportDone?received?.basis?.attributedTo==='player'&&received.basis.kind==='instruction'&&received.basis.situationId==='book.mol.visitor_branch'&&received.stage==='understood'&&a.facts['book.mol.surveyDelivered']===true:received==null&&a.facts['book.mol.surveyDelivered']==null,'Taiven needs actual delivered observer-qualified information.');
 if(state.actors[I.taiven].facts['book.mol.coverWilling'])assert(reportDone&&state.actors[I.taiven].completed['book.mol.npc.taiven_review']===1&&!!s.knowledge[I.taiven]?.['book.mol.private.review'],'Taiven’s willingness requires her own later finite review.');
 if(a.facts['book.mol.researchStanding'])assert(a.completed['book.mol.deposit_research']===1&&!!s.knowledge[I.ibery]?.['book.mol.receivedResearch'],'Research permission requires actual received account.');
 assert(Array.isArray(d.receipts)&&d.receipts.length<=128,'Invalid bounded Cyoria passage receipts.');for(const r of d.receipts){shape(r,['id','at','sequence'],'Cyoria receipt');assert(typeof r.id==='string'&&natural(r.at)&&r.at<=state.clock&&natural(r.sequence)&&r.sequence<=state.sequence,'Invalid Cyoria receipt time.');}
