export function nextMolBoundary(state){const d=state.motherOfLearning;if(!d||!activeMolVisit(state)||d.retrievalOpenedAt===null||!['offered','reachable'].includes(state.worlds[I.world].facts['book.mol.retrieval']))return Infinity;return state.clock+Math.max(0,d.retrievalOpenedAt+90-d.instances[0].clock.elapsed);}
const visitRoomOptions=additional=>({capacity:MOL_VISIT_CAPACITY,additional,synchronize:syncMolClock,validate:validateMolCampaignState});
